    // 2. Motion & Motion Equations
    list.add(
      SubjectMasterCategory(
        id = "sci_cat_2",
        categoryNumber = 2,
        titleSinhala = "චලිතය සහ චලිත සමීකරණ (Motion)",
        icon = "⚡",
        color = Color(0xFFEF4444),
        summary = "විස්ථාපනය, ප්‍රවේගය, ත්වරණය, ප්‍රවේග-කාල ප්‍රස්තාර සහ v=u+at සමීකරණ.",
        points = (1..20).map { i ->
          when (i) {
            1 -> SubjectFactPoint(1, "දුර සහ විස්ථාපනය", "දුර යනු ගමන් කළ මුළු මාර්ග දිගයි (අදිශ). විස්ථාපනය යනු නිශ්චිත දිශාවකට ආරම්භක ලක්ෂ්‍යයේ සිට සෘජු දුරයි (සදිශ).", "ඒකකය මීටර් (m) වේ.")
            2 -> SubjectFactPoint(2, "වේගය සහ ප්‍රවේගය", "වේගය = දුර / කාලය (අදිශ). ප්‍රවේගය = විස්ථාපනය / කාලය (සදිශ). ඒකකය ms⁻¹ වේ.", "දිශාව සහිත වීම ප්‍රවේගයේ වෙනසයි.")
            3 -> SubjectFactPoint(3, "ත්වරණය (Acceleration)", "ප්‍රවේගය වෙනස්වීමේ ශීඝ්‍රතාවයයි. a = (v - u) / t. ඒකකය ms⁻² වේ.", "ප්‍රවේගය අඩුවීම මන්දනය (Deceleration) වේ.")
            4 -> SubjectFactPoint(4, "ඒකාකාර ප්‍රවේගය", "වස්තුවක් සමාන කාල ප්‍රාන්තර වලදී නිශ්චිත දිශාවකට සමාන විස්ථාපන පසුකරයි නම් ත්වරණය ශුන්‍ය වේ.", "ප්‍රවේග-කාල ප්‍රස්තාරය තිරස් සරල රේඛාවකි.")
            5 -> SubjectFactPoint(5, "ඒකාකාර ත්වරණය", "සමාන කාල ප්‍රාන්තර වලදී ප්‍රවේගය එක සමාන ප්‍රමාණ වලින් වැඩිවීමයි.", "ප්‍රවේග-කාල ප්‍රස්තාරය නියත බෑවුමක් සහිත ආනත රේඛාවකි.")
            6 -> SubjectFactPoint(6, "ප්‍රවේග-කාල ප්‍රස්තාරයක අනුක්‍රමණය", "ප්‍රවේග-කාල ප්‍රස්තාරයේ අනුක්‍රමණයෙන් (Gradient) වස්තුවේ ත්වරණය (a) නිරූපණය වේ.", "අනුක්‍රමණය = ඍජු උස / තිරස් දුර = Δv / Δt.")
            7 -> SubjectFactPoint(7, "ප්‍රවේග-කාල ප්‍රස්තාරය යටතේ වර්ගඵලය", "ප්‍රවේග-කාල ප්‍රස්තාර රේඛාව සහ කාල අක්ෂය අතර ආවරණය වන වර්ගඵලයෙන් ගමන් කළ විස්ථාපනය (s) ලැබේ.", "ත්‍රිකෝණ, සෘජුකෝණාස්‍ර හෝ ත්‍රිපීසියම් වර්ගඵල සූත්‍ර යොදයි.")
            8 -> SubjectFactPoint(8, "පළමු චලිත සමීකරණය", "v = u + at (v = අවසාන ප්‍රවේගය, u = ආරම්භක ප්‍රවේගය, a = ත්වරණය, t = කාලය).", "නියත ත්වරණයෙන් චලනය වන වස්තු සඳහා පමණක් වලංගුය.")
            9 -> SubjectFactPoint(9, "දෙවන චලිත සමීකරණය", "s = ut + ½ at² (s = විස්ථාපනය).", "ආරම්භක නිශ්චලතාවයේ සිට (u=0) චලනය වන විට s = ½ at² වේ.")
            10 -> SubjectFactPoint(10, "තෙවන චලිත සමීකරණය", "v² = u² + 2as.", "කාලය (t) ලබාදී නොමැති විට ගණනය කිරීමට යොදාගනී.")
            11 -> SubjectFactPoint(11, "හතරවන චලිත සමීකරණය", "s = ((u + v) / 2) x t (සාමාන්‍ය ප්‍රවේගය x කාලය).", "ත්වරණය නොදන්නා විට යොදයි.")
            12 -> SubjectFactPoint(12, "ගුරුත්වජ ත්වරණය (g)", "පෘථිවි ගුරුත්වය යටතේ නිදහසේ වැටෙන වස්තුවක ත්වරණයයි. ආසන්න අගය g = 10 ms⁻² (හෝ 9.8 ms⁻²).", "ඉහළට විසි කරන විට a = -g ලෙස ගනී.")
            13 -> SubjectFactPoint(13, "සිරස්ව ඉහළට විසි කළ වස්තුවක්", "උපරිම උසට ළඟා වූ මොහොතේ අවසාන ප්‍රවේගය v = 0 වේ. a = -g.", "නැවත ආරම්භක ලක්ෂ්‍යයට පැමිණෙන විට එකම ප්‍රවේගය ගනී.")
            14 -> SubjectFactPoint(14, "විස්ථාපන-කාල ප්‍රස්තාරයක අනුක්‍රමණය", "විස්ථාපන-කාල ප්‍රස්තාරයේ අනුක්‍රමණයෙන් වස්තුවේ ප්‍රවේගය (v) ලැබේ.", "තිරස් රේඛාවක් මඟින් වස්තුව නිශ්චලව පවතින බව දක්වයි.")
            15 -> SubjectFactPoint(15, "අදිශ රාශි (Scalars)", "විශාලත්වයක් පමණක් ඇති දිශාවක් නැති භෞතික රාශි වේ. උදා: දුර, වේගය, ස්කන්ධය, කාලය, කාර්යය, ශක්තිය.", "සාමාන්‍ය වීජ ගණිත ක්‍රමයෙන් එකතු කළ හැක.")
            16 -> SubjectFactPoint(16, "සදිශ රාශි (Vectors)", "විශාලත්වයක් මෙන්ම නිශ්චිත දිශාවක්ද ඇති භෞතික රාශි වේ. උදා: විස්ථාපනය, ප්‍රවේගය, ත්වරණය, බලය, ගම්‍යතාව.", "සදිශ එකතු කිරීමේ ත්‍රිකෝණ නියමය යොදයි.")
